-- ---------- repair guides (~10) ----------
insert into repair_guides (fault_code_id, title, steps, source_ref, verified)
select f.id, g.title, g.steps::jsonb, g.ref, true
from (values
  ('P0300','Misfire diagnosis — W245 petrol (M266)',
   '["Read the freeze frame to identify which cylinder(s) misfired.","Inspect and, if due, replace spark plugs (NGK/Bosch spec for M266).","Swap the suspect ignition coil with another cylinder; see if the misfire follows it.","Inspect vacuum hoses and the intake manifold flap for leaks or sticking.","Clear the code and re-test drive; if it returns, check fuel pressure."]',
   'R-01 · W245 common-faults digest'),
  ('P0171','Lean mixture — air/vacuum check',
   '["Visually inspect intake boot and all vacuum hoses for cracks (heat-brittle on older W245).","Clean the MAF sensor with dedicated cleaner; compare MAF reading with spec.","Check long-term fuel trim at idle and at 2500 rpm (lean at both = delivery; lean at idle only = vacuum).","If trims normalise after a smoke test, repair the leaking hose and re-test."]',
   'R-02 · Fuel & air metering digest'),
  ('P0101','MAF sensor service — W245',
   '["Inspect the intake duct between MAF and throttle for tears.","Clean the MAF hot film with MAF-safe cleaner; never touch the film.","Compare live MAF g/s at idle against factory spec; replace if far off.","Clear codes and verify fuel trims return to ±5%."]',
   'R-02 · Fuel & air metering digest'),
  ('P0128','Thermostat replacement',
   '["Confirm with live data: coolant stuck below 80°C after 15 min of driving.","Drain coolant and replace the thermostat with gasket.","Refill and bleed the cooling system per W245 procedure.","Verify 87–95°C reached and held on a test drive."]',
   'R-03 · Cooling system digest'),
  ('P0410','Secondary air system check',
   '["Listen for the pump running 20–60 s after a cold start.","Inspect the combination valve for moisture corrosion (common failure).","Test pump output and hoses for blockage.","Replace the failed pump or valve; clear code and re-test cold start."]',
   'R-04 · Emissions digest'),
  ('P2004','Intake manifold flap service',
   '["Access the manifold flap linkage; check for free movement and carbon deposits.","Clean the flap and linkage; verify the actuator rod moves freely.","If the actuator motor is dead, replace the flap unit.","Clear codes and confirm the flap cycles on a live-data test."]',
   'R-05 · Manifold & induction digest'),
  ('P0670','Glow plug module — OM640 CDI',
   '["Measure glow plug resistance at the module connector (spec ~0.5–2 Ω).","Test module output during a cold start.","Replace the failed module or harness section.","Verify quick cold start after replacement."]',
   'R-06 · Diesel starting digest'),
  ('C1095','Steering angle sensor calibration',
   '["Perform the documented steering-angle zero calibration with the car on level ground.","Turn the steering lock-to-lock and back to centre per the procedure.","Clear codes; ESP/ABS lamps should extinguish.","If signals remain implausible, inspect the clockspring before replacing the sensor."]',
   'R-07 · ESP & chassis electronics digest'),
  ('B1048','Blower resistor replacement',
   '["Remove the passenger-side under-dash trim for resistor access.","Unplug and test the resistor pack; replace if open on any stage.","Check the blower motor brushes while the unit is exposed.","Reassemble and verify all blower speeds."]',
   'R-08 · HVAC & comfort digest'),
  ('P0562','Charging system diagnosis',
   '["Measure resting battery voltage (≥ 12.4 V healthy).","Measure charging voltage at idle: 13.8–14.6 V expected.","Inspect and clean the engine ground strap.","Replace the battery or alternator per findings."]',
   'R-09 · Electrical & SAM digest'),
  ('P0700','Autotronic CVT health check',
   '["Read the transmission control unit sub-codes (P0700 is a pointer).","Check CVT fluid level and condition; use only the specified fluid.","If fluid is degraded, service it and re-test.","Persistent sub-codes require a transmission specialist evaluation."]',
   'R-10 · Transmission & driveline digest'),
  ('U0100','CAN communication diagnosis',
   '["Test battery and charging system first — low voltage mimics bus faults.","Inspect CAN harness under the dash and at the SAM for corrosion or chafe.","Professional network diagnosis required if wiring checks clean."]',
   'R-09 · Electrical & SAM digest')
) as g(code, title, steps, ref)
join fault_codes f on f.code = g.code;

-- ---------- knowledge-base chunks (vector store; embeddings added by the RAG pipeline) ----------
-- Insert text chunks with zero vectors as placeholders; the LangChain.js ingestion job
-- replaces each placeholder vector with a real 768-dim embedding from the free embedding API.
insert into kb_chunks (guide_id, chunk_text, embedding, metadata)
select r.id, r.title || ' — ' || (r.steps->>0), '[0,0]'::vector(768),
  jsonb_build_object('code', f.code, 'system', f.system, 'severity', f.severity,
                     'make', 'mercedes-benz', 'model_scope', 'W245')
from repair_guides r
join fault_codes f on f.id = r.fault_code_id;

