-- placeholder vectors for the supplementary guides (replaced by /api/ingest embeddings)
insert into kb_chunks (guide_id, chunk_text, embedding, metadata)
select r.id, r.title || ' — ' || (r.steps->>0), '[0,0]'::vector(768),
  jsonb_build_object('code', f.code, 'system', f.system, 'severity', f.severity,
                     'make', 'mercedes-benz', 'model_scope', 'W245')
from repair_guides r
join fault_codes f on f.id = r.fault_code_id
where f.code in ('P0100','P0170','P0172','P0301','P0302','P0303','P0304','P0335','P0340','P0420','P0430','P0446','P0500','P0560','P0561','P0563','P0600','P0601','P0602','P0603','P0604','P0605','P0606','P0705','P0706','P0710','P0711','P0712','P0713','P0714','P0715','P0716','P0717','P0718','P0720','P0721','P0722','P0723','P0730','P0746-P0796','P0793','P0794','P0810','P0811','P0812','P0896','P1000','P1840-P1895','P240C','P1856','P1872','B1000','B1004','B1016','B1056','B1056-002','B1088','B1226','B1227','B1230','B1232','B1310','B1315','B1850','B1703','B2100','B1760','9022','9223','9243','900B','C1000','C1010','C1011','C1012','C1020','C1021','P0017','MOST ring open');

